import mq3.compat.numeric as numeric
import mq3.shared.q_shared_runtime as shared

function require(ok,text) if not ok then return error(7680,text) end if;return 1 end function
function main(args)
  checks=0
  checks=checks+require(shared.com_Clamp(0.0,1.0,-2.0)==0.0 and shared.com_Clamp(0.0,1.0,2.0)==1.0 and shared.com_Clamp(0.0,1.0,0.5)==0.5,"clamp")
  checks=checks+require(shared.com_SkipPath("a/b/c.tga")=="c.tga" and shared.com_SkipPath("a\\b")=="a\\b","skip path slash semantics")
  checks=checks+require(shared.com_StripExtension("a.b.c")=="a" and shared.com_StripExtension("plain")=="plain","strip first extension")
  checks=checks+require(shared.com_DefaultExtension("maps/q3dm1",64,".bsp")=="maps/q3dm1.bsp" and shared.com_DefaultExtension("maps/a.bsp",64,".cfg")=="maps/a.bsp","default extension")
  checks=checks+require(shared.shortSwap(0x1234)==0x3412 and shared.shortSwap(-2)==-257,"short swap")
  checks=checks+require(numeric.u32(shared.longSwap(0x12345678))==0x78563412 and shared.longNoSwap(-1)==-1,"long swap")
  value=bytes([1,2,3,4,5,6,7,8]);checks=checks+require(shared.long64Swap(value)==bytes([8,7,6,5,4,3,2,1]) and shared.long64NoSwap(value)==value,"long64 byte swap")
  checks=checks+require(numeric.floatBits(shared.floatSwap(numeric.bitsFloat(0x12345678)))==0x78563412,"float bit swap")
  checks=checks+require(shared.bigShort(0x1234)==0x3412 and shared.littleShort(0x1234)==0x1234 and shared.bigLong(0x12345678)==shared.longSwap(0x12345678) and shared.littleLong(7)==7,"host endian wrappers")
  checks=checks+require(shared.bigLong64(value)==shared.long64Swap(value) and shared.littleLong64(value)==value and shared.swap_Init()=="little","64 endian initialization")
  checks=checks+require(numeric.floatBits(shared.bigFloat(numeric.bitsFloat(0x12345678)))==0x78563412 and shared.littleFloat(1.25)==1.25,"float endian wrappers")
  session=shared.com_BeginParseSession("sample"," // line\n one \"two words\" /*x*/ three\nnext")
  checks=checks+require(shared.com_Parse(session)=="one" and shared.com_GetCurrentParseLine(session)>=1,"parse session and comments")
  checks=checks+require(shared.com_ParseExt(session,false)=="two words" and shared.com_Parse(session)=="three","quoted and regular tokens")
  checks=checks+require(shared.com_ParseExt(session,false)=="" and shared.com_Parse(session)=="next","line break policy")
  checks=checks+require(shared.com_ParseWarning(session,"warn")!="" and shared.com_ParseError(session,"bad")!="" and len(session.diagnostics)==2,"parse diagnostics")
  whitespace=shared.com_BeginParseSession("white"," \n\tvalue");checks=checks+require(shared.skipWhitespace(whitespace) and whitespace.state.line==1 and shared.com_Parse(whitespace)=="value","whitespace state")
  compressed=shared.com_Compress(" a   b // comment\n c /* block */ \" d   e \"\r\nf");checks=checks+require(compressed==" a b\nc \" d   e \"\nf","C source compression")
  braces=shared.com_BeginParseSession("braces","{ one { two } three } after");checks=checks+require(shared.skipBracedSection(braces)==0 and shared.com_Parse(braces)=="after","nested braced section")
  line=shared.com_BeginParseSession("line","abc def\nnext");shared.skipRestOfLine(line);checks=checks+require(shared.com_Parse(line)=="next" and line.state.line==1,"skip rest of line")
  match=shared.com_BeginParseSession("match","hello");checks=checks+require(shared.com_MatchToken(match,"hello")=="hello" and try(shared.com_MatchToken(shared.com_BeginParseSession("bad","x"),"y")) is error,"match token")
  one=shared.parse1DMatrix(shared.com_BeginParseSession("one","( 1 -2 3.5 )"),3);checks=checks+require(one[0]==1.0 and one[1]==-2.0 and one[2]==3.5,"1D matrix")
  two=shared.parse2DMatrix(shared.com_BeginParseSession("two","( ( 1 2 ) ( 3 4 ) )"),2,2);checks=checks+require(two==[[1.0,2.0],[3.0,4.0]],"2D matrix")
  three=shared.parse3DMatrix(shared.com_BeginParseSession("three","( ( ( 1 2 ) ) ( ( 3 4 ) ) )"),2,1,2);checks=checks+require(three[1][0][1]==4.0,"3D matrix")
  infos=shared.com_ParseInfos("{ name Sarge model sarge } { name Visor model visor }",4);checks=checks+require(len(infos)==2 and shared.info_ValueForKey(infos[1],"MODEL")=="visor","parse infos")
  checks=checks+require(shared.q_isprint(32) and not shared.q_isprint(127) and shared.q_islower(97) and shared.q_isupper(90) and shared.q_isalpha(66),"ASCII classifiers")
  checks=checks+require(shared.q_strrchr("abca",97)==3 and shared.q_strrchr("abc",0)==3 and shared.q_strrchr("abc",120)==-1,"reverse char search")
  checks=checks+require(shared.q_strncpyz("abcdef",4)=="abc" and try(shared.q_strncpyz("x",0)) is error,"bounded copy")
  checks=checks+require(shared.q_stricmpn("abc","ABd",2)==0 and shared.q_stricmpn("abc","ABd",3)<0 and shared.q_stricmp(void,"x")==-1,"case compare")
  checks=checks+require(shared.q_strncmp("abc","abd",3)<0 and shared.q_strncmp("abc","abd",2)==0,"byte compare")
  checks=checks+require(shared.q_strlwr("AbC1")=="abc1" and shared.q_strupr("aBc1")=="ABC1","case conversion")
  checks=checks+require(shared.q_strcat("abc",6,"defgh")=="abcde" and try(shared.q_strcat("abcd",4,"x")) is error,"bounded concatenate")
  clean=shared.q_CleanStr("^1Red\n\t^^caret");plen=shared.q_PrintStrlen("^1Red^^caret");checks=checks+require(plen==8 and clean=="Red^aret","color and printable cleaning got "+str(plen)+" / "+clean)
  checks=checks+require(shared.com_sprintf(8,"%s-%d",["abc",12345])=="abc-123" and shared.va("%s:%d:%x",["v",-2,255])=="v:-2:ff","typed formatting")
  text="\\name\\Sarge\\team\\red";checks=checks+require(shared.info_ValueForKey(text,"NAME")=="Sarge" and shared.info_Validate(text) and not shared.info_Validate("\\x\\bad;value"),"info lookup and validation")
  pair=shared.info_NextPair(text,0);checks=checks+require(pair.key=="name" and pair.value=="Sarge" and shared.info_NextPair(text,pair.head).key=="team","info pair iteration")
  checks=checks+require(shared.info_RemoveKey(text,"name")=="\\team\\red" and shared.info_RemoveKey_Big(text,"team")=="\\name\\Sarge","info removal")
  changed=shared.info_SetValueForKey(text,"name","Visor");checks=checks+require(changed=="\\name\\Visor\\team\\red","normal info replacement prepends")
  big=shared.info_SetValueForKey_Big(text,"map","q3dm1");checks=checks+require(big==text+"\\map\\q3dm1","big info append")
  checks=checks+require(shared.info_SetValueForKey(text,"bad;key","x")==text and shared.info_SetValueForKey(text,"name","")=="\\team\\red","invalid and empty info values")
  print("PASS: "+str(checks)+" complete q_shared.c runtime contracts");return 0
end function
